const buildCalendarData = () => {
  const base = createDate();

  const day20Date = new Date(base);
  day20Date.setDate(20);
  const day20String = DateHelper.toStringYYYYMMDD(day20Date);

  const day28Date = new Date(base);
  day28Date.setDate(28);
  const day28String = DateHelper.toStringYYYYMMDD(day28Date);

  return [
    {
      date: day20String,
      dateString: day20String,
      products: [
        {
          productId: 123,
          name: "Magic Concert",
          timeSlots: [
            {
              timeSlotId: 1,
              timeSlotFrom: `${day20String}T10:00:00`,
              timeSlotTo: `${day20String}T11:00:00`,
              quantity: 10,
              isFullDay: false,
            },
          ],
        },
      ],
    },
    {
      date: day28String,
      dateString: day28String,
      products: [
        {
          productId: 456,
          name: "Magic Concert",
          timeSlots: [
            {
              timeSlotId: 2,
              timeSlotFrom: `${day28String}T10:00:00`,
              timeSlotTo: `${day28String}T11:00:00`,
              quantity: 0,
              isFullDay: false,
            },
          ],
        },
      ],
    },
  ];
};

ProductCalendarService.getProductsCalendar = async (_glkId: number) => {
  const mockCalendarData = buildCalendarData();
  return mockCalendarData.map(
    (date, index) =>
      ({
        dateSlotId: index + 1,
        quantity: date.products.reduce(
          (sum, product) => sum + product.timeSlots.reduce((slotSum, slot) => slotSum + slot.quantity, 0),
          0,
        ),
        ...date,
      }) satisfies DateSlotItem,
  );
};

TimeSlotService.getTimeSlotAttraction = async (_glkId, dateString) => {
  const mockCalendarData = buildCalendarData();
  const found = mockCalendarData.find((d) => d.dateString === dateString);
  if (!found) return null;
  return {
    productId: found.products[0].productId,
    attractionId: 1,
    attractionName: found.products[0].name,
    timeSlots: found.products[0].timeSlots,
  } satisfies IGLKMyParksEntranceWithProductId;
};

