export const SelectDateAndTimeSlot: Story = {
  ...Primary,
  play: async ({ canvasElement }) => {
    const canvas = within(canvasElement as HTMLElement);

    const dateButton = await canvas.findByText("20");
    await userEvent.click(dateButton);

    const plusButton = await canvas.findByTestId("increase-button-Antal biljetter");
    await userEvent.click(plusButton);

    const quantitySelector = plusButton.parentElement;
    expect(quantitySelector).toHaveTextContent("1");

    const chooseTimeButton = await canvas.findByText("10:00");
    await userEvent.click(chooseTimeButton);

    expect(canvas.getByText("Lägg i varukorg")).toBeEnabled();
  },
};
